import{_ as e,o,c as a,ae as t}from"./chunks/framework.BuGep-IT.js";const u=JSON.parse('{"title":"エラー","description":"","frontmatter":{},"headers":[],"relativePath":"reference/errors.md","filePath":"reference/errors.md"}'),c={name:"reference/errors.md"};function s(n,r,l,d,i,h){return o(),a("div",null,[...r[0]||(r[0]=[t('<h1 id="errors" tabindex="-1">エラー <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;エラー {#errors}&quot;">​</a></h1><p><code>asyncmux</code> のカスタムエラークラスは多言語対応（i18n）を前提とした設計になっており、<code>i18n-error-base</code> をベースに構築されています。</p><h2 id="error-base" tabindex="-1"><code>ErrorBase</code> <a class="header-anchor" href="#error-base" aria-label="Permalink to &quot;`ErrorBase` {#error-base}&quot;">​</a></h2><p>すべての <code>asyncmux</code> エラーの基底クラスです。<code>i18n-error-base</code> の <code>I18nErrorBase</code> を継承し、メタデータ付きエラーおよび多言語メッセージをサポートします。</p><h2 id="decorator-support-error" tabindex="-1"><code>DecoratorSupportError</code> <a class="header-anchor" href="#decorator-support-error" aria-label="Permalink to &quot;`DecoratorSupportError` {#decorator-support-error}&quot;">​</a></h2><p>実行環境がステージ 3 のデコレーターをサポートしていない場合に投げられるエラーです。</p><h3 id="decorator-support-troubleshooting" tabindex="-1">対処 <a class="header-anchor" href="#decorator-support-troubleshooting" aria-label="Permalink to &quot;対処 {#decorator-support-troubleshooting}&quot;">​</a></h3><p>ステージ 3 のデコレーターをサポートしている実行環境、またはそれを再現した実装を用意する必要があります。</p><h2 id="lock-released-error" tabindex="-1"><code>LockReleasedError</code> <a class="header-anchor" href="#lock-released-error" aria-label="Permalink to &quot;`LockReleasedError` {#lock-released-error}&quot;">​</a></h2><p>すでに解放済みのロックを再度解放を試みた場合に投げられるエラーです。</p><h3 id="lock-released-troubleshooting" tabindex="-1">対処 <a class="header-anchor" href="#lock-released-troubleshooting" aria-label="Permalink to &quot;対処 {#lock-released-troubleshooting}&quot;">​</a></h3><p>すでに解放済みのロックを再度解放しないようにします。</p><h2 id="reentrant-lock-error" tabindex="-1"><code>ReentrantLockError</code> <a class="header-anchor" href="#reentrant-lock-error" aria-label="Permalink to &quot;`ReentrantLockError` {#reentrant-lock-error}&quot;">​</a></h2><p>デッドロックになるロックの再入 (再獲得) を検出した場合に投げられるエラーです。書き込みロックを保持しているクラスメソッドの実行中に、同じインスタンスに対して書き込みロックまたは読み取りロックを要求した場合や、読み取りロックを保持している状態で書き込みロックを要求した場合に投げられます。</p><h3 id="reentrant-lock-troubleshooting" tabindex="-1">対処 <a class="header-anchor" href="#reentrant-lock-troubleshooting" aria-label="Permalink to &quot;対処 {#reentrant-lock-troubleshooting}&quot;">​</a></h3><p>同じインスタンスのロック対象メソッド内から、そのインスタンスに対する書き込みロックを要求しないでください。読み取りロック同士の呼び出し (<code>@asyncmux.readonly</code> が付与されたメソッド内での <code>@asyncmux.readonly</code> が付与されたメソッドの呼び出し) は共有ロックとして許可されます。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>非同期処理コンテキストを利用できるランタイム (Node.js 22.3 以上、Bun など) では await をまたいだ再入も検出されますが、ブラウザーなど利用できない環境では同期的な呼び出し範囲のみ検出され、それ以外の再入はエラーにならずデッドロックします。</p></div>',17)])])}const b=e(c,[["render",s]]);export{u as __pageData,b as default};
